package com.keevo.shared.ai;

import java.util.List;

/**
 * Story 21.8 — one AI tool as the registry knows it: what a model sees ({@link #name}, {@link #description},
 * {@link #inputSchema}) and how it is gated (same declarations as the REST handler it mirrors).
 *
 * @param name        unique tool name ({@code @Tool(name)}), snake_case
 * @param description French description given to the model
 * @param inputSchema JSON schema of the arguments (generated by Spring AI from the method parameters)
 * @param module      module id of the {@code @RequiresEntitlement} gate (READ); {@code null} for an exempt tool
 * @param permissions the {@code @RequiresPermission} values (all required), empty when none
 * @param roleRule    the {@code @PreAuthorize} expression (method, else class), empty when none
 * @param handler     {@code Bean#method}, for the generated table and logs
 */
public record AiToolDescriptor(
        String name,
        String description,
        String inputSchema,
        String module,
        List<String> permissions,
        String roleRule,
        String handler
) {
}
